import{_ as e,o,c as a,a2 as i}from"./chunks/framework.D7WGirly.js";const h=JSON.parse('{"title":"Copilot — Advanced & Customization","description":"","frontmatter":{},"headers":[],"relativePath":"copilot-03-advanced-and-customization.md","filePath":"copilot-03-advanced-and-customization.md"}'),n={name:"copilot-03-advanced-and-customization.md"};function s(r,t,l,u,c,p){return o(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="copilot-—-advanced-customization" tabindex="-1">Copilot — Advanced &amp; Customization <a class="header-anchor" href="#copilot-—-advanced-customization" aria-label="Permalink to &quot;Copilot — Advanced &amp; Customization&quot;">​</a></h1><p><em>Getting the most from Copilot, rate limits, and workflow integration</em></p><hr><h2 id="how-intent-classification-works" tabindex="-1">How Intent Classification Works <a class="header-anchor" href="#how-intent-classification-works" aria-label="Permalink to &quot;How Intent Classification Works&quot;">​</a></h2><p>Copilot automatically decides whether to treat your message as a question (Chatbot mode) or an action request (Agentic mode). You never need to switch modes manually.</p><p>The classification is based on the language of your message and the context of your recent conversation. Messages that describe actions — &quot;create&quot;, &quot;add&quot;, &quot;update&quot;, &quot;list&quot;, &quot;generate&quot; — route to Agentic mode. Messages that ask questions or seek explanations — &quot;what&quot;, &quot;how&quot;, &quot;why&quot;, &quot;explain&quot; — route to Chatbot mode.</p><p>If a message is ambiguous, Copilot defaults to Chatbot mode and responds conversationally. You can always rephrase as an instruction if you wanted an action.</p><hr><h2 id="using-context-within-a-conversation" tabindex="-1">Using Context Within a Conversation <a class="header-anchor" href="#using-context-within-a-conversation" aria-label="Permalink to &quot;Using Context Within a Conversation&quot;">​</a></h2><p>Copilot maintains the context of your current conversation — up to the last several exchanges. This makes follow-up instructions natural:</p><ul><li>After searching for features, you can say &quot;update the first one to In Progress&quot; without re-specifying which feature</li><li>After creating a feature, you can say &quot;now add it to my Q3 roadmap&quot; and Copilot knows what &quot;it&quot; refers to</li><li>After generating a PRD, you can ask &quot;what&#39;s missing from this?&quot; and Copilot answers in the context of what it just created</li></ul><p>To keep Copilot on track during complex multi-step tasks, complete one logical sequence in one conversation before starting something entirely different.</p><hr><h2 id="giving-copilot-enough-context" tabindex="-1">Giving Copilot Enough Context <a class="header-anchor" href="#giving-copilot-enough-context" aria-label="Permalink to &quot;Giving Copilot Enough Context&quot;">​</a></h2><p>Agentic mode is most reliable when your workspace objects have clear, descriptive names. If you have three features with similar names, Copilot may ask you to confirm which one you mean. Using the feature key (e.g. FEAT-12) is always unambiguous.</p><p><strong>More reliable:</strong></p><blockquote><p>&quot;Update FEAT-12 to Completed&quot;<br> &quot;Generate a PRD for the feature called Single Sign-On&quot;</p></blockquote><p><strong>Less reliable:</strong></p><blockquote><p>&quot;Update the login feature&quot; (if multiple features have &quot;login&quot; in the name)</p></blockquote><hr><h2 id="rate-limits" tabindex="-1">Rate Limits <a class="header-anchor" href="#rate-limits" aria-label="Permalink to &quot;Rate Limits&quot;">​</a></h2><p>Copilot is subject to rate limiting per user to ensure platform stability for all users. If you hit a rate limit, Copilot will let you know. Wait a short time and then continue. There is no need to reload the page.</p><hr><h2 id="what-copilot-knows-about-your-workspace" tabindex="-1">What Copilot Knows About Your Workspace <a class="header-anchor" href="#what-copilot-knows-about-your-workspace" aria-label="Permalink to &quot;What Copilot Knows About Your Workspace&quot;">​</a></h2><p>In Agentic mode, Copilot can access:</p><ul><li>Your backlog items (features): name, key, status, description</li><li>Your roadmaps (projects): name, list of features</li><li>Your releases: name, status, feature count</li><li>Your strategies: name</li></ul><p>It does not currently have access to:</p><ul><li>Customer quotes attached to features</li><li>Evaluation scores or RICE/custom field values</li><li>Financial Forecast models or assumptions</li><li>Bento Grids or export history</li><li>Competitive Intelligence reports</li></ul><p>This means Copilot is best used for structural and workflow tasks — creating, organizing, and updating objects — rather than analytical tasks that depend on scores or evidence.</p><hr><h2 id="using-copilot-alongside-other-modules" tabindex="-1">Using Copilot Alongside Other Modules <a class="header-anchor" href="#using-copilot-alongside-other-modules" aria-label="Permalink to &quot;Using Copilot Alongside Other Modules&quot;">​</a></h2><p>Copilot works best as an accelerator for tasks you&#39;d otherwise do manually. Common patterns:</p><p><strong>Rapid feature capture:</strong> When you&#39;re in a meeting and ideas are coming fast, open Copilot and dictate features by name. &quot;Create a feature called X, create a feature called Y...&quot; — then organize and score them in the backlog afterward.</p><p><strong>Post-extract action:</strong> After reviewing Extracts, instead of navigating to each feature to generate a PRD, ask Copilot: &quot;Generate PRDs for all features related to onboarding.&quot; (Note: this works best when features are named clearly.)</p><p><strong>Roadmap assembly:</strong> Create a new Roadmap and add multiple features to it in a single conversation, then open the Roadmap to review and organize the hierarchy visually.</p><p><strong>Document generation in bulk:</strong> Rather than opening each feature detail page to generate documents, ask Copilot to generate them for specific features by name or key.</p><hr><p><em>Next: Troubleshooting &amp; FAQs — what to do when Copilot doesn&#39;t behave as expected.</em></p>',38)])])}const m=e(n,[["render",s]]);export{h as __pageData,m as default};
